; Hand-written: one function per case for the immediate propagation of peephole-copies
; (propagate_imm in src/peephole/dead_regs.c), run.sh says what each must become. main
; fills a few words of RAM, calls every function (R7 is 0 or 1 for the branchy ones) and
; stores each R0, so v32sim sees a wrong rewrite. Generated by a script; edit the output.

  %define global_x 300

__function_leaf:
  mov R0, 1
  ret

; ----- the MOV Rt, imm is propagated into its one or two uses and removed

__function_fire_src:
  mov R0, [200]
  mov R1, 5
  iadd R0, R1
  ret

__function_fire_src_two:
  mov R0, [200]
  mov R2, [201]
  mov R1, 5
  iadd R0, R1
  imul R2, R1
  iadd R0, R2
  ret

__function_fire_cmp:
  mov R0, [200]
  mov R1, 5
  ilt R0, R1
  ret

__function_fire_load:
  mov R1, global_x
  mov R0, [R1]
  ret

__function_fire_load_num:
  mov R1, 301
  mov R0, [R1]
  ret

__function_fire_store:
  mov R0, [200]
  mov R1, 302
  mov [R1], R0
  ret

__function_fire_store_load:
  mov R0, [200]
  mov R1, 303
  mov [R1], R0
  mov R0, [R1]
  iadd R0, 1
  ret

; ----- nothing is propagated

__function_keep_third_use:
  mov R0, [200]
  mov R2, [201]
  mov R3, [202]
  mov R1, 5
  iadd R0, R1
  iadd R2, R1
  iadd R3, R1
  iadd R0, R2
  iadd R0, R3
  ret

__function_keep_float:
  mov R0, [200]
  mov R1, 1.5
  iadd R0, R1
  ret

__function_keep_fadd:
  mov R0, [200]
  mov R1, 5
  fadd R0, R1
  ret

__function_keep_label:
  mov R0, [200]
  mov R1, 5
__keep_label_l:
  iadd R0, R1
  ret

__function_keep_jump:
  mov R0, [200]
  mov R1, 5
  jt R7, __keep_jump_l
  iadd R0, R1
__keep_jump_l:
  iadd R0, R1
  ret

__function_keep_live_after:
  mov R0, [200]
  mov R1, 5
  iadd R0, R1
  jt R7, __keep_la_x
  ret
__keep_la_x:
  iadd R0, R1
  ret

__function_keep_call_between:
  mov R0, [200]
  mov R1, 5
  call __function_leaf
  iadd R0, R1
  ret

__function_keep_offset:
  mov R1, 300
  mov R0, [R1+1]
  ret

__function_keep_store_value:
  mov R0, [200]
  mov R2, [203]
  mov R1, 5
  mov [R2], R1
  ret

__function_keep_dst_use:
  mov R0, [200]
  mov R1, 5
  iadd R1, R0
  mov [204], R1
  ret

__function_keep_volatile_use:
  mov R1, 306
  mov R0, [R1]   ;@v
  ret

__function_keep_volatile_mov:
  mov R1, 306   ;@v
  mov R0, [R1]
  ret

